from flask import Flask, jsonify, request

app = Flask(__name__)


@app.get("/search")
def search():
    # GET /search?q=flask&page=2&tag=api&tag=web
    query = request.args.get("q", "")
    page = request.args.get("page", default=1, type=int)
    tags = request.args.getlist("tag")
    return jsonify({"query": query, "page": page, "tags": tags})


@app.post("/login")
def login():
    # тело формы: email=a%40b.ru&password=secret
    email = request.form.get("email", "")
    password = request.form.get("password", "")
    return jsonify({"email": email, "password_length": len(password)})


@app.post("/tasks")
def create_task():
    # тело JSON: {"title": "Купить молоко"}
    data = request.get_json(silent=True)
    if data is None:
        return jsonify({"error": "ожидали JSON в теле запроса"}), 400
    title = data.get("title")
    if not isinstance(title, str) or not title.strip():
        return jsonify({"error": "поле title обязательно"}), 422
    return jsonify({"id": 1, "title": title.strip()}), 201


app.run(debug=True)

from flask import Flask, jsonify, redirect, render_template, request, url_for

app = Flask(__name__)

USERS = {}
NEXT_ID = 1


def validate_signup(data):
    errors = []
    email = data.get("email", "")
    password = data.get("password", "")
    if not email:
        errors.append("email обязателен")
    elif "@" not in email:
        errors.append("email некорректен")
    if len(password) < 8:
        errors.append("password должен быть не короче 8 символов")
    return errors


@app.get("/signup")
def signup_form():
    return render_template("signup.html")


@app.post("/signup")
def signup_submit():
    global NEXT_ID
    errors = validate_signup(request.form)
    if errors:
        return jsonify({"errors": errors}), 400
    USERS[NEXT_ID] = request.form.get("email")
    user_id = NEXT_ID
    NEXT_ID += 1
    return redirect(url_for("profile", user_id=user_id))   # 302, а не HTML


@app.get("/users/<int:user_id>")
def profile(user_id):
    email = USERS.get(user_id)
    if email is None:
        return jsonify({"error": "пользователь не найден"}), 404
    return jsonify({"id": user_id, "email": email})


app.run(debug=True)

